/* Runs only inside the self-contained review file. All actions mutate synthetic memory. */
const inventory = JSON.parse(document.getElementById('route-data').textContent);
for (const route of inventory.routes) {
  route.sourceUrl = `https://github.com/workforceap/workforceap-beta/blob/${inventory.baseSha}/${route.source}`;
  route.titleBasis = inventory.titleBases[route.titleBasis];
}
const journeySpecs = JSON.parse(document.getElementById('journey-data').textContent);
const routes = inventory.routes;
const screenDefinitions=JSON.parse(document.getElementById('screen-definitions').textContent).screens;
let data = createFixture();
let currentPath = '/dashboard';
let current = resolveRoute(currentPath,routes);
let mode = 'ready';
const REVIEW_APPEARANCE_KEY = 'wap-portal-review-appearance';
const reviewSystemTheme = window.matchMedia('(prefers-color-scheme: dark)');
const validAppearance = value => ['light','dark','system'].includes(value) ? value : 'system';
function storedAppearance(){
  try{return validAppearance(localStorage.getItem(REVIEW_APPEARANCE_KEY));}
  catch{return 'system';}
}
let themePreference = storedAppearance();
let theme = themePreference === 'system' ? (reviewSystemTheme.matches ? 'dark' : 'light') : themePreference;
function applyReviewAppearance(){
  theme = themePreference === 'system' ? (reviewSystemTheme.matches ? 'dark' : 'light') : themePreference;
  document.documentElement.dataset.theme = theme;
  document.documentElement.dataset.themePreference = themePreference;
  const control = document.getElementById('theme-select');
  if(control){
    control.value = themePreference;
    control.title = themePreference === 'system' ? `System appearance (${theme})` : `${theme === 'dark' ? 'Dark' : 'Light'} appearance`;
  }
}
function setReviewAppearance(value){
  themePreference = validAppearance(value);
  try{localStorage.setItem(REVIEW_APPEARANCE_KEY,themePreference);}catch{/* Storage may be unavailable in an embedded review. */}
  // Only change the palette. Rebuilding the workspace would disturb focus,
  // text selections, in-progress form edits and the current voice session.
  applyReviewAppearance();
}
reviewSystemTheme.addEventListener('change',()=>{
  if(themePreference === 'system')applyReviewAppearance();
});
window.addEventListener('storage',event=>{
  if(event.key !== REVIEW_APPEARANCE_KEY && event.key !== null)return;
  themePreference = event.key === null ? storedAppearance() : validAppearance(event.newValue);
  applyReviewAppearance();
});
applyReviewAppearance();
let catalogRole = 'all';
let catalogTab = 'screens';
let formRevision = 1;
let requestSequence = 0;
let lastUncertainKey = null;
let activeDialogTrigger = null;
let pendingEntry = null;
