 const isBlog=p.includes('blog'),isInvite=p.includes('invite'),isPlacement=p.includes('placement');let fields=isBlog?field('Article title','title','A practical guide to getting started')+field('URL slug','slug','sample-guide')+field('Article body','text','','textarea',true):isInvite?field('Recipient email','email','sample@example.invalid','email')+field('Intended role','role','Member','select:Member|Counselor|Employer|Partner')+field('Invitation note','text','','textarea',true):isPlacement?field('Member','name','Alex Morgan')+field('Employer','employer','Example Technology Co.')+field('Role','title','IT Support Specialist')+field('Evidence source','source','Member reported','select:Member reported|Staff verified')+field('Supporting notes','text','','textarea',true):field('Record name','name',current.role==='member'?'Alex Morgan':'Sample record')+field('Contact email','email','sample@example.invalid','email')+field('Notes for this record','text','','textarea',true);
