 if(p.includes('lab-reviews'))return data.lab.submission?section('Submitted practice',table(['Member','Submission','Status','Next step'],[[esc(data.profile.name),'Troubleshoot a support request',tag(data.lab.submission.status,'info'),link('/counselor/lab-reviews/[submissionId]','Review evidence','button small')]])):stateView('empty','No submitted practice yet','Private member drafts do not appear in the staff queue. Use the sample lab to exercise explicit sharing.','Open sample member lab','/dashboard/learning/labs/[labId]');
