function stateView(type,title,description,label='Try again',path=null){const heading=title||({loading:'Loading your workspace',empty:'Nothing here yet',unavailable:'We couldn’t check this right now',denied:'You don’t have access to this record',conflict:'This record changed while you were working','not-found':'That screen isn’t available'}[type]||'Review this state');if(type==='loading')return `<section class="section" aria-busy="true" aria-label="Loading sample state"><h2>${heading}</h2><p class="muted">The shell and your current location stay available.</p><div class="skeleton short"></div><div class="skeleton block"></div><div class="skeleton"></div><div class="skeleton"></div>${action('Complete sample load','retry','button')}</section>`;return `<section class="section empty" data-state="${type}">${icon(type==='denied'?'lock':type==='unavailable'||type==='conflict'?'alert':'file')}<h2>${esc(heading)}</h2><p>${esc(description||({empty:'A confirmed empty result gives you a useful next action. It does not stand in for a failed lookup.',unavailable:current&&/resume/.test(current.route)?'We couldn’t check your résumé right now. Your draft is preserved. Try again.':'Your draft and selected record are preserved. Try again, or return to the previous screen.',denied:'Access is decided by your signed-in identity and saved relationship. Contact your team if you need help.',conflict:'Your changes are still here. Review the latest version before saving again.','not-found':'The route does not resolve to a known screen. Use the workspace navigation to continue.'}[type]||''))}</p><div class="actions">${path?link(path,label,'button primary'):action(type==='denied'?'Return to workspace':type==='conflict'?'Review latest version':label,type==='denied'?'home':'retry','button primary')}${type==='unavailable'?action('Show preserved draft','show-draft','button'):''}</div></section>`;}
